#!/usr/bin/env python3
"""Send commands to the QEMU monitor socket at /tmp/qemu-monitor.sock."""
import socket, sys, time

SOCK = "/tmp/qemu-monitor.sock"


def run(cmds, delay=0.4):
    s = socket.socket(socket.AF_UNIX)
    s.connect(SOCK)
    s.settimeout(0.6)

    def drain():
        out = b""
        try:
            while True:
                d = s.recv(4096)
                if not d:
                    break
                out += d
        except Exception:
            pass
        return out.decode(errors="replace")

    drain()
    res = []
    for c in cmds:
        s.sendall(c.encode() + b"\n")
        time.sleep(delay)
        res.append(drain())
    s.close()
    return "".join(res)


if __name__ == "__main__":
    sys.stdout.write(run(sys.argv[1:]))

#!/usr/bin/env python3
"""Boot-and-observe helper for the trial VM (monitor socket path as arg)."""
import socket, sys, time
from PIL import Image

SOCK = sys.argv[1] if len(sys.argv) > 1 else "/tmp/t.sock"
TAG = sys.argv[2] if len(sys.argv) > 2 else "x"

s = socket.socket(socket.AF_UNIX)
s.connect(SOCK)
s.settimeout(1.0)


def drain():
    out = b""
    try:
        while True:
            d = s.recv(65536)
            if not d:
                break
            out += d
    except Exception:
        pass
    return out.decode(errors="replace")


def cmd(c, wait=0.6):
    s.sendall(c.encode() + b"\n")
    time.sleep(wait)
    return drain()


def shot(name):
    cmd('screendump "/tmp/%s.ppm"' % name, 2.0)
    im = Image.open("/tmp/%s.ppm" % name)
    im.save("/app/%s.png" % name)
    print(name, im.size, im.convert("L").getextrema(), flush=True)


drain()
for i, step in enumerate(sys.argv[3:]):
    if step.startswith("sleep:"):
        time.sleep(float(step.split(":")[1]))
    elif step.startswith("shot:"):
        shot("%s_%s" % (TAG, step.split(":")[1]))
    else:
        print(cmd(step).strip()[-300:], flush=True)

