#!/usr/bin/env python3
"""Type text / send keys to a QEMU monitor socket, then optionally screendump.

Usage: keys.py <sock> <tag> 'type:cd \\windows' 'key:ret' 'sleep:3' 'shot:a'
"""
import socket, sys, time
from PIL import Image

SPECIAL = {
    "\\": "backslash",
    " ": "space",
    ".": "dot",
    ",": "comma",
    "-": "minus",
    "=": "equal",
    ";": "semicolon",
    "/": "slash",
    "'": "apostrophe",
    "[": "bracket_left",
    "]": "bracket_right",
    "\n": "ret",
    ":": "shift-semicolon",
    "_": "shift-minus",
}


def keyname(ch):
    if ch in SPECIAL:
        return SPECIAL[ch]
    if ch.isalpha():
        return ch.lower()
    if ch.isdigit():
        return ch
    raise ValueError("no key for %r" % ch)


def main():
    sock, tag = sys.argv[1], sys.argv[2]
    s = socket.socket(socket.AF_UNIX)
    s.connect(sock)
    s.settimeout(0.3)

    def drain():
        try:
            while s.recv(65536):
                pass
        except Exception:
            pass

    def send(c, w=0.25):
        s.sendall(c.encode() + b"\n")
        time.sleep(w)
        drain()

    drain()
    for step in sys.argv[3:]:
        kind, _, val = step.partition(":")
        if kind == "type":
            for ch in val:
                send("sendkey " + keyname(ch), 0.12)
        elif kind == "key":
            for k in val.split("+"):
                send("sendkey " + k, 0.3)
        elif kind == "sleep":
            time.sleep(float(val))
        elif kind == "shot":
            send('screendump "/tmp/%s_%s.ppm"' % (tag, val), 2.0)
            im = Image.open("/tmp/%s_%s.ppm" % (tag, val))
            im.save("/app/%s_%s.png" % (tag, val))
            print(tag, val, im.size, im.convert("L").getextrema(), flush=True)
        elif kind == "mon":
            send(val, 0.6)


if __name__ == "__main__":
    main()

# noVNC web front-end for the Windows 3.11 QEMU VM (VNC :1 / port 5901)
server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://127.0.0.1:6080;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }

    location = /vnc {
        return 302 /vnc.html?host=$host&port=80&path=websockify&autoconnect=true&resize=scale;
    }

    location /websockify {
        proxy_pass http://127.0.0.1:6080/websockify;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 3600s;
        proxy_send_timeout 3600s;
    }
}

# noVNC web front-end for the Windows 3.11 QEMU VM (VNC :1 / port 5901).
# Used as: nginx -c /app/nginx-novnc.conf
user  www-data;
worker_processes  auto;
pid  /run/nginx.pid;

events {
    worker_connections  1024;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;
    sendfile      on;
    access_log    /var/log/nginx/novnc-access.log;
    error_log     /var/log/nginx/novnc-error.log;

    server {
        listen 80 default_server;
        listen [::]:80 default_server;
        server_name _;

        # noVNC static files + websockify, both served by websockify on 6080
        location / {
            proxy_pass http://127.0.0.1:6080;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_read_timeout 3600s;
            proxy_send_timeout 3600s;
        }

        location = /vnc {
            return 302 "/vnc.html?path=websockify&autoconnect=true&resize=scale";
        }

        location /websockify {
            proxy_pass http://127.0.0.1:6080/websockify;
            proxy_http_version 1.1;
            proxy_set_header Upgrade $http_upgrade;
            proxy_set_header Connection "upgrade";
            proxy_read_timeout 3600s;
            proxy_send_timeout 3600s;
        }
    }
}

